class Solution { private fun feasible(amount:Long,budget:Int,composition:List<List<Int>>,stock:List<Int>,cost:List<Int>):Boolean{for(recipe in composition){var spent=0L;for(metal in stock.indices){val shortage=amount*recipe[metal]-stock[metal];if(shortage>0){spent+=shortage*cost[metal];if(spent>budget)break}};if(spent<=budget)return true};return false}fun maxNumberOfAlloys(n:Int,k:Int,budget:Int,composition:List<List<Int>>,stock:List<Int>,cost:List<Int>):Int{var upper=0L;for(recipe in composition){var machineUpper=Long.MAX_VALUE;for(metal in 0 until n){val individuallyAffordable=stock[metal].toLong()+budget/cost[metal];machineUpper=minOf(machineUpper,individuallyAffordable/recipe[metal])};upper=maxOf(upper,machineUpper)};var low=0L;var high=upper+1;while(low+1<high){val middle=(low+high)/2;if(feasible(middle,budget,composition,stock,cost))low=middle else high=middle};return low.toInt()} }
